import type {Lesson,LearningLevel,Reference} from './learning-types';
const r=(label:string,url:string):Reference=>({label,url});
const nist=r('NIST: Statistical methods handbook','https://www.itl.nist.gov/div898/handbook/');
const ai=r('NIST: AI Risk Management Framework','https://www.nist.gov/itl/ai-risk-management-framework');
const ml=r('Google: Machine Learning Crash Course','https://developers.google.com/machine-learning/crash-course');
const pmi=r('PMI: Project management resources','https://www.pmi.org/learning/library');
const solver=r('Frontline: Decision modeling under uncertainty','https://www.solver.com/robust-decision-making');
const mcda=r('UK Government: Multi-criteria analysis manual','https://www.gov.uk/government/publications/multi-criteria-analysis-manual-for-making-government-policy');
const ethics=r('UNESCO: Ethics of artificial intelligence','https://www.unesco.org/en/artificial-intelligence/recommendation-ethics');
function t(slug:string,title:string,level:LearningLevel,definition:string,explanation:string,why:string,terms:[string,string][],steps:[string,string][],example:string,walkthrough:string[],pitfall:string,question:string,answer:string,practiceQuestion:string,practiceAnswer:string,prerequisites:string[],sources:Reference[]):Lesson{
 return {slug,title,category:'AI',level,definition,explanation,example,pitfall,question,answer,prerequisites,sources,guide:{why,terms,steps,walkthrough,practice:{question:practiceQuestion,answer:practiceAnswer}}};
}
// Original independent study material. Course outlines inform topic selection, not copied teaching text.
export const courseLessons:Lesson[]=[
t('framing-uncertainty-whatif','Framing decisions, uncertainty and what-if analysis','Beginner',
'A decision model separates objectives, available actions, assumptions and uncertain outcomes. What-if analysis explores how a specified change in inputs alters a modeled result.',
'Risk can sometimes be described using justified probabilities; other uncertainty may involve poorly known probabilities, missing alternatives or disagreement about the model itself. Variability is a property of outcomes, not automatically a measurement error. Begin by defining the decision-maker, deadline, feasible alternatives and relevant consequences. Best-case and worst-case scenarios reveal a range under chosen assumptions but do not assign probabilities. A decision should account for important nonfinancial effects and identify evidence that could change the recommendation.',
'Learn to turn a vague business problem into alternatives and distinguish a scenario from a forecast or probability distribution.',
[['Objective','The outcome or value a decision is intended to improve.'],['Scenario','A specified combination of assumptions used to explore consequences.'],['Decision variable','An action or quantity that the decision-maker can choose.']],
[['Define the boundary','For a capacity choice, state the period, who is served, budget limits and unacceptable outcomes. Include the current process or doing nothing as an explicit alternative where feasible. The model should not quietly omit affected groups.'],
['Separate control from uncertainty','Order quantity is chosen; demand is uncertain. Unit cost may be fixed for the decision period or may itself be uncertain. Label each input so a solver cannot accidentally improve results by choosing an uncontrollable quantity.'],
['Explore and communicate assumptions','Use a spreadsheet with clearly separated inputs, formulas and outputs. Change one assumption at a time for basic sensitivity, then inspect coherent combined scenarios. Best and worst cases can be informative but should not be called likely without evidence.']],
'A fictional school chooses between renting a small or large projector kit for an event. The large option serves more attendees but costs more. Attendance is unknown, and the school also values accessibility and reliability.',
['List costs, capacities and consequences for each alternative, including what happens when attendance exceeds capacity.','Calculate results under low and high attendance. Do not assume attendance takes whichever value makes an alternative look best.','Identify the attendance level or risk tolerance at which the choice changes, and explain any outcomes that cannot be reduced to one financial total.'],
'Using precise numbers for weakly justified assumptions can make a model seem more certain without adding evidence.',
'Does a best-case scenario describe the most likely outcome?',
'No. It specifies favorable assumptions. Likelihood requires separate probability reasoning, and the scenario may be deliberately extreme.',
'Why should a model include the option to keep the current process?',
'It provides a relevant baseline and opportunity-cost comparison. Otherwise a team may choose the best of several unnecessary changes.',
['probability-distributions'],[solver,mcda]),
t('monte-carlo-dependence-sensitivity','Monte Carlo simulation, dependence and tornado charts','Intermediate',
'Monte Carlo simulation repeatedly samples uncertain inputs and computes outcomes. Sensitivity analysis examines which assumptions drive results and how conclusions change.',
'A simulation makes an uncertainty model explicit; it does not discover the correct distribution automatically. Define input distributions, dependence, formulas, decision variables and outputs. Repeated trials approximate the outcomes of that model. A larger trial count reduces sampling noise but does not repair biased inputs or missing mechanisms. Tornado charts often rank one-at-a-time input effects, while simulation-based sensitivity may use other methods. Interpret the chart’s construction before treating its ranking as causal importance.',
'Learn to build and interpret a small simulation, preserve dependence and distinguish precision from validity.',
[['Trial','One sampled set of inputs and its resulting outputs.'],['Dependence','A relationship between uncertain inputs that affects their joint behavior.'],['Tornado chart','An ordered display of sensitivity effects under a defined analysis method.']],
[['Represent uncertainty plausibly','Use data or justified elicitation to choose distributions and bounds. Demand, delay and cost can be linked. Sampling them independently when adverse events move them together can understate severe outcomes. Correlation alone may not describe every important tail relationship.'],
['Calculate repeated outcomes','In Excel or Analytic Solver, keep inputs and formulas auditable, set decision values, run trials and inspect means, percentiles and threshold probabilities. Check reproducibility settings where applicable and compare simple limiting cases with hand calculations.'],
['Interpret and challenge results','Report model assumptions, trial count, uncertainty and consequential tail outcomes. Vary distribution and dependence assumptions. A tornado ranking based on a chosen input range changes if that range changes; it is not proof that intervening on the variable will have the predicted causal effect.']],
'A toy demand model assigns 0, 10 and 20 units with probabilities 0.2, 0.5 and 0.3. A stock decision of 10 creates a shortage exactly in the 20-unit scenario under this model. Simulation should approximate a shortage frequency of 30 percent over many trials.',
['Map a uniform random draw into the three outcome ranges, or use the tool’s discrete distribution capability.','For each trial calculate max(demand − stock, 0). Summarize average shortage and the fraction of trials with any shortage.','Check that results approach the hand-calculated model values, then test whether different probabilities or correlated supply delays change the decision. Do not confuse this check with validation of real demand.'],
'More simulation trials can make a wrong model’s answer look impressively stable.',
'Would doubling the trial count correct an omitted correlation between supply delays and demand?',
'No. It only samples the specified model more precisely. The dependence structure must be modeled appropriately.',
'What should be checked before interpreting the longest tornado bar as the most important real-world cause?',
'Check the output, input ranges, other inputs held fixed and construction method. Sensitivity under a model is not automatically causal evidence.',
['probability-distributions','framing-uncertainty-whatif'],[solver,nist]),
t('decision-trees-emv-information','Decision trees, expected monetary value and break-even sensitivity','Intermediate',
'A decision-analysis tree represents choices, chance events and consequences in their information order. It differs from a machine-learning decision tree used for prediction.',
'Decision nodes identify actions under the decision-maker’s control; chance nodes represent uncertain events with appropriate probabilities. Terminal branches contain consequences such as net payoffs. Working backward averages chance outcomes and selects among feasible decisions under the chosen objective. Expected monetary value is useful under its assumptions but does not represent every decision-maker’s risk preferences or ethical constraints. Sensitivity and break-even analysis show when a recommendation changes as uncertain inputs vary.',
'Learn to construct a sequential choice, calculate expected monetary value and identify information that would be available before each action.',
[['Chance node','A point where uncertainty determines which outcome follows.'],['Rollback','Evaluating a decision tree from terminal outcomes back toward the start.'],['Break-even threshold','An input value at which modeled alternatives have equal value.']],
[['Respect the information sequence','Place a test or observation before a later action only if it will actually be known then. Allowing an early decision to depend on a future outcome gives the model unrealistic foresight. A prediction is not perfect information.'],
['Calculate branch values','At a chance node, use probabilities that sum to one across its possible outcomes. Include all relevant costs and avoid double counting them along paths. At a decision node, apply the stated preference or objective rather than averaging actions together.'],
['Test the recommendation','Vary influential probabilities and payoffs, calculate switching thresholds and communicate downside outcomes. A positive expected value can hide a severe loss that the decision-maker cannot afford or is not entitled to impose on others.']],
'A fictional pilot costs $20. If successful, its benefit before that cost is $100; otherwise the benefit is zero. With success probability p, net expected value is 100p − 20. Doing nothing has a modeled payoff of zero.',
['At p = 0.4, expected net value is $20. Individual net outcomes remain $80 or −$20, not a guaranteed $20.','Set 100p − 20 = 0 to find the 0.2 break-even probability under these simplified assumptions.','A proposed test is valuable only insofar as its information can improve the later choice enough to justify its cost and limitations. Recompute conditional decisions rather than assuming every extra test pays.'],
'A tree with correct arithmetic can still be misleading if probabilities, feasible actions, timing or risk preferences are wrong.',
'Are a prediction tree and a decision-analysis tree the same method?',
'No. One learns predictive splits from data; the other represents choices, chance outcomes and consequences for a decision.',
'If success probability is 0.1 in the example, what is expected net value?',
'100 × 0.1 − 20 = −$10. Under an expected-money objective and these assumptions, doing nothing is preferable, but other objectives require explicit analysis.',
['probability-distributions','framing-uncertainty-whatif'],[solver,mcda]),
t('mcda-direct-pairwise','Multi-criteria decisions: direct rating, weights and pairwise comparison','Intermediate',
'Multi-criteria decision analysis structures choices involving several objectives. Direct ratings score alternatives on criteria; pairwise approaches compare elements two at a time.',
'A weighted score combines judgments under a defined model, not a universally objective truth. Criteria should represent distinct concerns and use clearly defined scales. Weights reflect trade-offs over specified ranges, so a weight is not meaningful independently of how scores are constructed. Pairwise comparisons can help people articulate priorities, but inconsistent judgments and workload grow with the number of elements. Explain whose values are represented, how disagreement is handled and which requirements cannot be traded away.',
'Learn to calculate a transparent weighted score and examine whether its scales, weights and assumptions support the decision.',
[['Criterion','A dimension used to evaluate an alternative.'],['Normalization','Transforming measures to a comparison scale under stated rules.'],['Compensation','Allowing a strong score on one criterion to offset a weak score on another.']],
[['Define criteria and constraints','Distinguish desirable features from mandatory thresholds. A system that fails a required privacy condition may need exclusion rather than a small penalty balanced by low cost. Avoid counting the same benefit twice under correlated criteria.'],
['Elicit scores and trade-offs','For direct rating, define anchored meanings and which direction is better. In pairwise comparison, record how strongly one criterion is preferred relative to another under a specified method. Review inconsistent comparisons rather than letting software conceal them.'],
['Assess robustness and explain','Compare rankings under plausible weights and scores. If a tiny change reverses the result, report that fragility. A group decision may require presenting disagreement rather than averaging away a conflict about values.']],
'Two fictional software options receive benefit scores on a common 0–100 scale. A has usability 80 and reliability 60; B has usability 60 and reliability 90. With weights 0.4 and 0.6, A scores 68 and B scores 78.',
['Calculate A: 0.4 × 80 + 0.6 × 60 = 68. Calculate B: 0.4 × 60 + 0.6 × 90 = 78.','Change usability weight to 0.8 and reliability to 0.2. A becomes 76 and B becomes 66, reversing the ranking.','Discuss whether the trade-offs and scores are credible and whether either option fails a mandatory requirement. The changing result shows the role of values, not a mathematical error.'],
'Weights and normalized scores can embed subjective choices even when the final calculation is fully reproducible.',
'Why should an MCDA report show sensitivity to weights?',
'It reveals whether the preferred option is robust or depends narrowly on uncertain or disputed judgments.',
'In pairwise judgments, A strongly outranks B and B strongly outranks C, but C strongly outranks A. What needs attention?',
'The judgments may be inconsistent under the chosen framework. Review meanings and evidence rather than presenting an unexplained ranking as objective.',
['framing-uncertainty-whatif'],[mcda,r('NIST: AHP in multi-criteria evaluation','https://www.nist.gov/publications/assessing-performance-residential-energy-management-control-algorithms-multi-criteria-0')]),
t('mcda-ideal-outranking','Ideal-point and outranking methods: choosing without hiding trade-offs','Advanced',
'Ideal-point methods compare alternatives with a defined best or reference profile. Outranking methods assess whether evidence supports preferring one alternative to another, potentially allowing incomparability.',
'There is no single MCDA technique best for every decision. A distance-to-ideal approach needs normalization, criterion direction, weights and a distance definition. Some methods also compare with an anti-ideal. Outranking methods can use agreement, disagreement and veto thresholds rather than a single fully compensatory average. They may leave alternatives incomparable or tied. These results can honestly represent conflicting objectives rather than a software failure. Model selection should reflect the decision’s structure, evidence and acceptable trade-offs.',
'Learn to explain how method choice affects a ranking and when a noncompensatory rule is more defensible than a single score.',
[['Ideal point','A chosen reference with desired or best criterion values.'],['Outranking','A structured relation supporting preference under specified evidence rules.'],['Veto','A sufficiently serious disadvantage that blocks a preference under a method’s rules.']],
[['Make scales and direction explicit','A smaller cost is better while a larger reliability score may be better. Distances are meaningless if one raw unit dominates only because of its scale. Normalization changes geometry and may affect results, so document it and test alternatives.'],
['Match compensation to the decision','A weighted distance can permit a major weakness to be offset elsewhere. If some harm is unacceptable, a hard constraint or suitable veto may reflect the decision better. Outranking still requires justified thresholds and stakeholder judgments.'],
['Compare methods transparently','Explain difficulty, implementation burden, data needs and ease of communicating the result. If rankings differ, inspect the assumptions that produced the difference. Do not select whichever method happens to favor a previously preferred option.']],
'On already comparable benefit scales, an ideal is (100,100). Option A is (90,40) and B is (60,80). With equal squared-distance weights, A’s squared distance is 10² + 60² = 3,700; B’s is 40² + 20² = 2,000.',
['Under that simplified distance rule, B is closer. This conclusion depends on the scales, ideal and distance definition.','If the second criterion must be at least 70, A fails a mandatory threshold regardless of its first score. Exclusion is different from assigning a modest penalty.','An outranking analysis could consider criterion-level agreement and a veto under its chosen variant. Report the specific rules instead of assuming every outranking method uses the same formula.'],
'A method that produces a total ranking can conceal genuine incomparability, uncertainty or an unacceptable trade-off.',
'Is an incomparable pair necessarily a failed analysis?',
'No. It can reflect insufficient evidence or conflicting criteria under a method that intentionally permits incomparability. Further deliberation or information may be needed.',
'Why should raw dollars and reliability percentages not be inserted unexamined into a Euclidean distance?',
'Their units and ranges differ. The resulting distance could mostly reflect numerical scale rather than intended importance; normalization and justified trade-offs are needed.',
['mcda-direct-pairwise'],[mcda,r('UK Government: MCDA supplementary guidance','https://www.gov.uk/government/publications/green-book-supplementary-guidance-multi-criteria-decision-analysis')]),
t('optimization-chance-recourse','Optimization under uncertainty, chance constraints and recourse','Advanced',
'Optimization selects decisions under an objective and constraints. With uncertainty, a model must also specify distributions or scenarios and when decisions can adapt to new information.',
'Simulation evaluates consequences for a fixed policy; simulation optimization searches across policies using simulated outcomes. Stochastic programming represents uncertain scenarios and can include later recourse actions. Robust approaches seek performance across a specified uncertainty set. A chance constraint requires a condition to hold with at least a chosen probability under the model. These formulations differ in assumptions and feasible solution methods. Software support depends on the actual mathematical structure and product version, not simply the presence of a Solver button.',
'Learn to distinguish an uncertain input from a controllable choice, and a here-and-now decision from an action permitted after uncertainty resolves.',
[['First-stage decision','An action selected before specified uncertainty is observed.'],['Recourse','An adaptive later decision made with information legitimately then available.'],['Chance constraint','A probabilistic condition under a stated uncertainty model.']],
[['Define timing and information','For event staffing, base staff may be committed before attendance is known. Overtime or contracted backup may be chosen later if available. A model must not let first-stage staffing vary with future attendance as though the manager already knew it.'],
['Choose an objective and risk rule','Expected cost, downside risk and service probability answer different questions. “Meet demand with probability at least 0.95” permits modeled failure in up to 5 percent of cases; it is not a guarantee for every event. Inspect consequences of those failures.'],
['Validate the recommended policy','Use appropriate solver methods, check feasibility and evaluate the selected policy on independent scenarios where possible. Searching many policies against one simulation sample can overfit that sample. Test distribution, dependence and resource-availability assumptions.']],
'A toy event has demand of 50 people with probability 0.8 and 100 with probability 0.2. Each staff member serves 10 people. Assume service capacity is the only constraint and staff cannot be added later.',
['Five staff meet demand only in the 50-person case, giving modeled service probability 0.8. Ten staff meet both cases, giving probability 1.','A 0.95 chance constraint rejects five staff under this discrete example. Intermediate staffing below ten still fails the 100-person case.','If later backup is allowed, specify its cost, response time and capacity, then model it as recourse. Do not assume backup is instantly available or free.'],
'An optimal answer is optimal only for the stated model; inaccurate probabilities, omitted constraints or impossible recourse can invalidate the operational recommendation.',
'Does a 95 percent chance constraint mean the service cannot fail?',
'No. It is a probability requirement under the model, with specified assumptions and allowed failure probability. Real performance may differ.',
'Why evaluate an optimized policy using fresh scenarios?',
'The search may exploit noise or peculiarities in the scenarios used during optimization. An independent evaluation helps assess how the policy generalizes under the model.',
['monte-carlo-dependence-sensitivity','business-math-nonlinear-models'],[solver,mcda]),
t('fairness-hiring-social-sorting','Fairness, hiring-system bias and social sorting','Intermediate',
'An algorithmic fairness audit examines who benefits, who is harmed and whether a system’s data, objectives and workflow create unjustified differences or exclusion.',
'Bias can enter through historical decisions, recruitment, measurement, labels, feature choices, evaluation and deployment. Removing a protected characteristic does not remove correlated proxies or correct an unfair target. Fairness criteria can conflict: equal selection rates, equal error rates and calibration answer different questions. Social sorting concerns how categories and scores shape access to opportunities and treatment over time. Evaluate the institution and decision process, not only a model in isolation. A fairness metric is evidence for deliberation, not an automatic legal or ethical verdict.',
'Learn to audit an AI hiring scenario, interpret subgroup evidence and design a meaningful correction and appeal process.',
[['Proxy','A variable conveying information related to another characteristic.'],['Disparate impact','A concern about adverse group effects from a practice, interpreted under the relevant legal and institutional context.'],['Sociotechnical system','People, institutions, data and technology acting together.']],
[['Question the target and measurement','Past hiring outcomes are not neutral labels of ability if past selection was discriminatory. A game score must be relevant and validated for the job rather than merely easy to collect. Missing accommodations or unequal access can affect who appears in the data.'],
['Compare harms with context','Inspect sample sizes, selection rates, false negatives and other important errors across relevant groups and intersections. Large uncertainty can make a clean-looking percentage unreliable. Ask which criterion fits the decision and whose interests it prioritizes.'],
['Build recourse into the workflow','Provide understandable information, correction of inaccurate data and review by a person with authority to change the result. Monitor subsequent outcomes and barriers to appeal. A rubber-stamp human reviewer is not meaningful oversight.']],
'In a fictional screening exercise, 20 of 100 applicants in group A and 10 of 100 in group B are shortlisted. The selection-rate gap is 10 percentage points. That observation requires investigation; it neither proves a specific cause nor establishes compliance.',
['Check who applied, what was measured and whether job-relevant criteria and accommodations were applied consistently.','Inspect labeled outcomes and error rates rather than declaring the historical shortlist to be ground truth. Test plausible proxy and measurement effects.','Document the decision owner, explanation, appeal and data-correction route. Verify that a corrected record can actually lead to a changed outcome.'],
'Do not infer individual ability, character or deservingness solely from demographic group averages or model-created categories.',
'Would deleting gender and ethnicity columns guarantee a fair hiring system?',
'No. Proxies, biased labels, unequal measurement and workflow design can preserve harm. Audit the entire decision process and its consequences.',
'A human approves every recommendation without time or authority to investigate. Is that meaningful oversight?',
'Not merely because a person is present. Oversight requires information, competence, time and power to challenge and change the decision.',
['precision-and-recall','data-leakage'],[ai,ethics]),
t('interpretability-transparency','Interpretability, transparency and post-hoc explanations','Advanced',
'Interpretability is not one universally agreed property. Transparency about a model’s operation, an explanation of a particular output and a justification for a decision are different goals.',
'Begin by specifying who needs to understand what and for which decision. A developer debugging a model, an auditor examining group harms and an applicant contesting a rejection need different information. A simple model with many engineered or opaque variables can be difficult to understand. A post-hoc explanation approximates or describes behavior after the fact; it is not automatically the model’s internal mechanism or proof of causation. Lipton’s analysis cautions against treating the word interpretable as self-evident.',
'Learn to evaluate an explanation against its intended use instead of assuming that a readable chart makes a system trustworthy.',
[['Transparency','Visibility into relevant design, data, behavior or process under a specified meaning.'],['Post-hoc explanation','An explanation produced after a model’s output, potentially by a separate method.'],['Fidelity','How accurately an explanation reflects the behavior it claims to describe.']],
[['State the explanatory question','Ask whether the goal is debugging, checking consistency, enabling an appeal or understanding a causal mechanism. These goals require different evidence. A feature-attribution display may help one task while failing to justify a consequential policy.'],
['Inspect assumptions and stability','Explanations can depend on the background data, feature representation and treatment of correlated variables. Small input changes or different methods may alter the story. Check whether a local approximation remains valid in the neighborhood where it is used.'],
['Connect explanation to action','An affected person needs a way to correct errors or contest the criterion, not just a technical score breakdown. A suggested change should be feasible and legitimate. Altering a proxy to improve a score does not prove a causal improvement in the desired outcome.']],
'A hypothetical applicant is told that an employment-gap feature reduced their score. That message might identify a model association, but it does not show that the gap is job-relevant or that the underlying employment record is correct.',
['Identify the source of the explanation: the original model, a local surrogate or a later narrative generator.','Test whether the explanation consistently reflects actual model behavior and whether correlated features change the attribution.','Offer record correction and a substantive review of the criterion. Do not equate explaining a harmful rule with justifying it.'],
'A plausible natural-language rationale can be generated without faithfully representing how the system reached its result.',
'Does a linear model automatically provide a sufficient explanation for every user?',
'No. Feature meanings, transformations, scale, number of inputs and the user’s task matter. Simplicity of mathematical form is not the same as useful understanding.',
'Can an explanation establish that a feature causes success at work?',
'Not from predictive attribution alone. A causal claim needs suitable design and assumptions beyond explaining a model’s associations.',
['causal-inference','fairness-hiring-social-sorting'],[r('Lipton: The Mythos of Model Interpretability','https://arxiv.org/abs/1606.03490'),ai]),
t('research-integrity-chrysalis','Research integrity, publication bias and the Chrysalis effect','Advanced',
'Research integrity preserves an honest relationship between questions, methods, evidence and reported conclusions. Selective reporting can make a literature appear more decisive than the underlying research.',
'Fabrication invents evidence; falsification misrepresents research processes or data. Questionable practices also include presenting a post-hoc hypothesis as planned, selectively dropping unfavorable results or searching analyses without disclosing the search. The Chrysalis effect describes how selective changes between initial research and publication can make results look more successful. This concern does not mean every revised analysis is misconduct: justified exploratory work is valuable when transparently labeled. Citation count and polished presentation do not substitute for checking methods and evidence.',
'Learn to distinguish exploration from confirmation and preserve a research trail when using AI to generate or summarize claims.',
[['Preregistration','A time-stamped statement of intended questions and methods before relevant results are examined.'],['Publication bias','A published record distorted by selective availability of results.'],['HARKing','Presenting a hypothesis developed after seeing results as though it had been specified beforehand.']],
[['Preserve the original question','Record the initial protocol, outcome definitions and analysis plan. Explain legitimate changes and their timing. The purpose is to let readers distinguish tests of prior claims from discoveries generated by the same data.'],
['Report the analytical search','Document exclusions, alternative specifications, missing results and uncertainty. Replication checks whether findings transfer to additional evidence. Reproducibility of code is useful but does not by itself establish that the design or interpretation is valid.'],
['Check sources and participant obligations','Verify citations and quotations against real publications, including corrections. For human-participant research, consult the relevant ethics-review and consent requirements before collecting or reusing data. AI tools do not inherit permission to process identifiable participant material.']],
'A fictional researcher tries 20 outcomes and finds one small p-value. Reporting only that outcome as the original hypothesis conceals the search and exaggerates how surprising the result is under the intended interpretation.',
['Keep the full set of outcomes and explain which were planned. Do not invent a prior prediction to match the favorable result.','Label the unexpected pattern exploratory and consider an appropriate multiplicity analysis. A new independent test can assess the resulting hypothesis.','If an AI assistant supplies supporting references, open them and inspect the relevant passages. Fabricated or irrelevant citations cannot become evidence through repetition.'],
'Retelling an exploratory result as a planned success can mislead even when no individual data point has been fabricated.',
'Is it wrong to change a hypothesis after exploring data?',
'Not automatically. Exploration generates useful hypotheses. The problem is hiding that timing or presenting the same-data discovery as independent confirmation.',
'Does a highly cited article require no further scrutiny?',
'No. Inspect design, data, relevance, uncertainty and correction status. Popularity and authority are not substitutes for evidential support.',
['hypothesis-testing-ab','hallucination-and-calibration'],[r('O’Boyle and colleagues: The Chrysalis Effect','https://journals.sagepub.com/doi/10.1177/0149206314527133'),r('Canadian research ethics: TCPS 2','https://ethics.gc.ca/eng/policy-politique_tcps2-eptc2_2022.html')]),
t('ethical-frameworks-governance','AI ethics frameworks, governance architecture and sandboxes','Intermediate',
'AI governance assigns decision rights, evidence requirements, controls and accountability across a system’s lifecycle. Ethical principles become useful when they change operational choices.',
'Frameworks discuss concerns such as benefit, avoiding harm, autonomy, justice, transparency and accountability. UNESCO, AI4People and risk-management approaches organize these ideas differently; they are not interchangeable legal certificates. A governance architecture specifies who approves data use, evaluates risk, authorizes launch, investigates incidents and hears appeals. A sandbox is a bounded environment for learning under controls, not an exemption from obligations. Laws such as the EU AI Act have specific scope, roles and evolving implementation details that require current authoritative guidance.',
'Learn to turn an ethical commitment into a testable process and distinguish governance, voluntary guidance and law.',
[['Accountability','Responsibility linked to an answerable decision owner and meaningful consequences.'],['Sandbox','A controlled testing setting with defined boundaries and safeguards.'],['Guardrail','A constraint or condition a system must respect.']],
[['Start from affected people and use','Identify plausible benefits, harms, power imbalances and alternatives. A low-risk drafting assistant and a high-impact selection system need different controls. Include people affected by decisions as stakeholders rather than only product buyers.'],
['Translate principles into controls','“Fairness” might require a documented criterion, subgroup evaluation, accessible review and monitored outcomes. Specify evidence, owners and escalation paths. “Human oversight” must include capacity and authority to stop or change behavior.'],
['Use bounded experimentation','Define permitted data, users, duration, review, stop triggers and exit conditions. Test whether safeguards work before scaling. Legal compliance is jurisdiction-specific; maintain a review process instead of treating a framework checklist as permanent clearance.']],
'A fictional organization wants to pilot a hiring recommender. Its sandbox uses approved nonproduction candidate scenarios, forbids employment decisions and requires documented review before any real-world use.',
['Record who approves the experiment and what information may be used. Do not assume a “pilot” label authorizes personal-data processing.','Test biased scenarios, explanation quality, appeal handling and failure reporting. Capture evidence of limitations as well as success.','Decide whether to stop, redesign or progress under explicit criteria. A successful sandbox demonstration is not automatic permission for production hiring decisions.'],
'An ethics board without information, resources or authority can become ceremonial rather than an effective control.',
'How does a principle differ from an operational governance control?',
'A principle expresses a value. A control identifies actions, evidence, owners and consequences that make the value influence actual decisions.',
'Does a voluntary AI ethics framework prove legal compliance?',
'No. Law, contracts and professional obligations have their own scope. Use authoritative current advice for the relevant jurisdiction and activity.',
['fairness-hiring-social-sorting','ai-project-lifecycle-strategy'],[ethics,ai,r('European Commission: AI Act framework','https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai'),r('AI4People ethical framework','https://link.springer.com/article/10.1007/s11023-018-9482-5')]),
t('transaction-costs-expertise-power','AI, transaction costs, expertise and institutional power','Advanced',
'Transaction costs are the effort and resources involved in finding information, negotiating, coordinating, checking and enforcing exchanges. AI can redistribute these costs and the power associated with them.',
'Generating a document cheaply does not make verifying it free. An organization may save expert drafting time while transferring review, correction or dispute costs to employees, customers or institutions. Changes in who controls data, models and explanations can concentrate expertise and dependency. Institutional trust depends on justified confidence in procedures and remedies, not only output quality. Analyze both direct production costs and the governance work needed to make exchanges reliable. A local efficiency gain may create larger costs elsewhere.',
'Learn to identify where AI shifts work and bargaining power, and evaluate governance as part of the business design.',
[['Verification cost','Effort needed to check a claim, output or transaction.'],['Information asymmetry','Unequal access to relevant knowledge between parties.'],['Institutional legitimacy','Justified acceptance of an institution’s authority and processes.']],
[['Map the full transaction','List discovery, generation, coordination, checking, correction and enforcement activities. Identify who performs and pays for each. A reduction in the vendor’s cost does not show an equivalent benefit for every participant.'],
['Examine expertise and dependency','Automation can make useful capability accessible while reducing opportunities to practice judgment or challenge the provider. Ask who can inspect evidence, switch suppliers, contest a result and maintain operations if the system is unavailable.'],
['Design governance with the cost model','Allocate responsibility and funding for review and appeal. Preserve records needed to resolve disputes, while minimizing unnecessary personal data. Evaluate whether the institution can absorb errors instead of shifting all burden to less powerful users.']],
'A fictional firm reduces contract drafting from 10 hours to 2 using AI, but each recipient now spends 12 hours checking invented clauses. The firm’s private efficiency improved while the wider transaction became more costly.',
['Measure drafting and verification separately and name the parties carrying those costs.','Investigate whether better templates, source grounding or expert review can reduce the recipient’s burden.','Include correction and dispute processes in the operating model. Do not describe the 8-hour private saving as an 8-hour social benefit without examining transferred work.'],
'Cheap generation can increase the volume of material requiring scarce human verification and weaken trust if accountability is absent.',
'Can AI lower one organization’s cost while increasing total system cost?',
'Yes. It can transfer review, correction and enforcement work to other participants. The evaluation boundary determines which effects are visible.',
'Why can preserving expert review be valuable even if it reduces an apparent speed gain?',
'It may prevent costly errors and maintain the ability to judge, contest and repair decisions. Efficiency should include the cost of trustworthy outcomes.',
['ethical-frameworks-governance','generative-ai-business-value'],[ai,ethics]),
t('reflective-cognition-innovation','Reflective cognition, AI entrepreneurship and professional judgment','Intermediate',
'Reflective cognition examines how conclusions were reached, what assumptions shaped them and how alternative evidence might change them. AI can support this process or displace it through uncritical reliance.',
'An assistant can generate alternatives, challenge a draft or suggest a prototype, but fluency can also encourage automation bias. Comparing an independently formed judgment with an AI response makes differences visible. Entrepreneurship uses experimentation to test a problem, value proposition and feasible business model; a generated pitch does not establish customer need. In advisory or counseling-like settings, authenticity, trust and professional boundaries matter alongside efficiency. Preserve human responsibility for consequential interpretations and do not treat an AI system as a substitute for a qualified professional.',
'Learn to use AI as a structured critic while preserving independent reasoning, evidence checks and responsibility.',
[['Automation bias','A tendency to accept automated suggestions without adequate scrutiny.'],['Reflexivity','Examining how one’s position, assumptions and tools influence an inquiry.'],['Value proposition','The benefit offered to a particular user or customer.']],
[['Form a view before requesting a critique','Write the problem, your initial interpretation and the evidence you rely on. This creates a comparison point. If the assistant frames the issue first, its assumptions can become invisible defaults that shape all later reasoning.'],
['Compare reasons rather than polish','Ask where the assistant disagrees, which evidence supports it and what alternatives were omitted. Verify references and identify uncertainty. Agreement with the assistant may reflect shared blind spots rather than confirmation.'],
['Test ideas outside the conversation','For a proposed venture, talk to relevant users, observe behavior and run bounded tests of the claimed benefit. Keep consent, professional responsibilities and confidentiality in view. A convincing narrative cannot establish demand, clinical usefulness or ethical acceptability.']],
'A fictional founder proposes an AI study tool. Before consulting an assistant, they write that students struggle mainly with finding definitions. The assistant suggests an elaborate feature set, but interviews reveal the real difficulty is applying examples.',
['Preserve the initial claim and compare it with actual interview evidence. Do not count AI enthusiasm as customer validation.','Build a small example-based prototype and observe whether learners can solve a new problem afterward.','Record which assumptions changed and why. Retain responsibility for claims made to users, even if the assistant helped write them.'],
'Repeatedly asking for confirmation can create a persuasive loop without producing independent evidence.',
'Why write an independent assessment before asking AI for feedback?',
'It helps reveal framing influence, disagreements and changes in reasoning. Otherwise the assistant’s initial response can become the unexamined reference point.',
'Does a polished AI-generated business plan show that a market exists?',
'No. Market evidence comes from relevant customers, behavior and appropriate experiments, not the completeness or confidence of a generated document.',
['hallucination-and-calibration','generative-ai-business-value'],[ethics,ai]),
t('ai-ip-liability-accountability','Intellectual property, hallucination and managerial responsibility','Advanced',
'Responsible AI use distinguishes permission to access material, permission to reuse it and responsibility for the decisions or publications built from it.',
'Publicly accessible information is not automatically licensed for every use. Inputs, training material, generated outputs and third-party quotations raise different ownership and contractual questions. Attribution is valuable but does not itself grant permission. Hallucinated sources, invented accusations and false professional claims can create serious harms. Liability depends on facts, jurisdiction, contracts and professional roles; there is no universal “AI wrote it” exemption. Managers should maintain evidence, review and escalation processes rather than relying on a generic disclaimer to make every use acceptable.',
'Learn to identify rights and responsibility questions before publishing or deploying AI-assisted work.',
[['Licence','Permission subject to specified terms; it can differ from simple access.'],['Provenance','Information about the origin and transformation of material.'],['Review owner','A person with responsibility and authority to approve a use.']],
[['Check input and output permissions','Know whether confidential records, copyrighted documents or participant data may be supplied to a provider. Generated material can contain recognizable third-party content. Check the relevant provider terms, source rights and intended use rather than assuming ownership from possession.'],
['Verify consequential claims','Open cited sources and compare the actual evidence with each claim. A fabricated citation or unsupported allegation must not pass review because it sounds plausible. Keep correction routes and an audit trail proportionate to the risks.'],
['Assign responsibility before release','Identify who approves content, responds to complaints, investigates incidents and obtains legal or professional advice when needed. A contract can allocate responsibilities but does not automatically eliminate mandatory obligations or harms to third parties.']],
'A fictional newsletter assistant drafts a claim about a company and cites an article that does not exist. It also includes a long paragraph copied from another publisher. The owner cannot make these problems disappear by labeling the page “AI-generated.”',
['Verify the factual claim against real evidence and remove or correct unsupported statements before publication.','Review the copied material’s licence and applicable rules; replace it with original analysis or obtain suitable permission rather than relying only on a source link.','Keep a reachable correction and rights-contact process, and assign responsibility for responding. Seek qualified advice for consequential uncertain uses.'],
'Disclaimers, attribution and AI disclosure can improve transparency without conferring blanket permission or immunity.',
'Does giving credit to a source automatically authorize reproducing its article?',
'No. Attribution and permission are separate. Applicable licences, exceptions, contracts and law depend on the actual use and context.',
'A manager says the provider is responsible for every error because it generated the text. What is missing?',
'The organization’s own selection, publication, review and contractual or professional responsibilities still need examination. Responsibility cannot be assumed away by pointing to the tool.',
['ethical-frameworks-governance','research-integrity-chrysalis'],[ethics,ai,r('Canada: Copyright Act','https://laws-lois.justice.gc.ca/eng/acts/C-42/')]),
t('business-math-nonlinear-models','Turning business problems into mathematical and nonlinear models','Intermediate',
'A mathematical model represents a business question using defined quantities, relationships, objectives and constraints. Nonlinear relationships allow effects that do not follow one constant slope.',
'Begin with the action the organization can take and the outcome it needs to predict or improve. Distinguish a decision variable under its control from an uncertain input and an outcome. A predictive regression describes a conditional relationship; an optimization model chooses actions under assumptions. A polynomial term can model curvature, while interactions let one feature’s effect depend on another. Flexibility can improve fit but increase extrapolation risk and overfitting. Mathematical precision is useful only when the represented question is appropriate.',
'Learn to translate a verbal case into a checkable model and explain why prediction does not automatically tell a manager what to do.',
[['Decision variable','A quantity the decision-maker can choose within the model.'],['Constraint','A limit a feasible decision must satisfy.'],['Interaction','A relationship where one variable’s effect depends on another variable.']],
[['Define quantities and units','For staffing, distinguish scheduled staff, customer arrivals, service rate, waiting time and cost. Some are choices and others uncertain inputs or outputs. Mixing customers per hour with customers per day can invalidate an otherwise plausible equation.'],
['Choose a defensible relationship','A linear relationship assumes a constant marginal slope under its formulation. Squared terms, transformations and interactions represent different shapes. Examine plots, residuals and domain knowledge rather than adding complexity merely to improve training fit.'],
['Connect results to action','Compare with a baseline, use held-out evaluation and consider how errors affect the decision. A model predicting high demand does not decide staffing unless an objective, capacity constraints and service trade-offs are specified. Communicate assumptions in business terms.']],
'A toy revenue model uses price p and predicted demand q(p). If q(p) = 100 − 2p, then predicted revenue is p × q(p) = 100p − 2p². Revenue is nonlinear in price even though the assumed demand equation is linear.',
['At price 10, predicted demand is 80 and revenue is 800. At price 20, demand is 60 and revenue is 1,200.','Neither result includes costs, capacity, competition or uncertainty. Limit the relevant price range so the demand equation is not used to predict impossible negative demand.','Choose a pricing objective and appropriate constraints before treating a high predicted revenue as a recommendation. Validate the demand model on relevant evidence.'],
'A model can be mathematically correct and still answer the wrong managerial question or extrapolate beyond the evidence.',
'Is a regression coefficient automatically the effect of changing a business policy?',
'No. It may describe association influenced by confounding or selection. A policy intervention needs causal reasoning and a feasible decision model.',
'Why should a staffing model distinguish demand from staffing decisions?',
'Demand is uncertain and not directly chosen by the manager, while staffing is a controllable action. Confusing them can let an optimizer “solve” the problem by choosing unrealistic demand.',
['linear-and-logistic-regression','overfitting-and-regularization'],[ml,nist]),
t('time-series-forecasting','Time-series forecasting, seasonality and backtesting','Intermediate',
'A time series records observations in order. Forecasting estimates future values using information available at a particular time, with uncertainty that depends on horizon and assumptions.',
'Time order changes evaluation. A random split can train on the future while testing on the past, producing an unrealistic assessment. Trend, seasonality, irregular events and changing relationships require different treatments. Naïve forecasts, moving averages and exponential smoothing provide useful baselines; more elaborate models should demonstrate added value. Prediction intervals describe a model’s uncertainty about future observations and differ from intervals for a mean parameter. External inputs must themselves be available or forecast when the prediction is made.',
'Learn to recognize temporal structure, compare a forecast with a simple baseline and evaluate it as it would have been used.',
[['Horizon','How far into the future a forecast extends.'],['Seasonality','A recurring pattern associated with a defined period.'],['Backtest','A historical simulation of forecasting using only information then available.']],
[['Inspect the series before fitting','Check regular spacing, missing periods, unit changes and one-time disruptions. A weekly seasonal pattern differs from a long-run trend. Plot the original scale and investigate whether apparent structure is created by reporting changes.'],
['Use a sensible baseline','For repeated weekly patterns, last week’s corresponding period can be a useful seasonal baseline. A moving average smooths noise but may lag a trend. Exponential smoothing weights observations according to its formulation. Compare candidate methods at the actual decision horizon.'],
['Evaluate rolling forward','Train up to a cutoff, forecast the next interval, then move the cutoff forward. Aggregate relevant error measures and inspect bias, costly peaks and interval coverage. Percentage error measures can behave badly near zero; choose metrics that fit the data and decision.']],
'A fictional store sells 100, 120, 110 and 130 units in four consecutive weeks. A four-week moving-average forecast is 115 units. That simple calculation ignores seasonality, promotions and stockouts, so it is a baseline rather than a complete demand model.',
['Choose the forecast origin: only those four weeks are available at that moment. Calculate (100 + 120 + 110 + 130) ÷ 4 = 115.','After the next actual week arrives, measure its forecast error. Do not revise the original prediction using that new outcome before evaluating it.','Repeat over multiple cutoffs and compare with a seasonal or other appropriate baseline. Record major event assumptions separately and communicate uncertainty.'],
'A low average error can hide systematic underprediction during the highest-demand periods that matter most for capacity.',
'Why is a random train-test split often inappropriate for forecasting?',
'It can expose the model to later observations or related future information, so the test no longer represents the information available at forecast time.',
'If next month’s promotion schedule is unknown, may a backtest use its actual realized values as forecast inputs?',
'Not as though they were known. Model their availability realistically, supply forecast assumptions or label the result as a different conditional scenario.',
['data-leakage','probability-distributions'],[r('Snowflake: Time-series forecasting','https://docs.snowflake.com/en/user-guide/ml-functions/forecasting'),nist]),
t('analytics-deployment-snowflake','Deploying predictive analytics with Snowflake and operational controls','Intermediate',
'Deployment makes a model usable in a live workflow. A cloud data warehouse such as Snowflake can support data preparation, scheduled scoring and analytics, but requires explicit permissions and operational ownership.',
'A notebook or spreadsheet result is not yet a production service. Operationalization needs a stable data contract, reproducible transformation, versioned model, controlled access, a scoring schedule or interface, and a response when data or predictions are unavailable. Batch scoring and interactive scoring serve different needs. Snowflake’s available features and account capabilities can evolve, so implementation should follow current documentation rather than a memorized screen sequence. Integration is as much a process and accountability problem as a technical one.',
'Learn to design a defensible path from an evaluated model to operational use and identify the responsibilities a deployment diagram can conceal.',
[['Scoring','Applying a selected model to input records.'],['Data contract','Agreed meanings, types, availability and quality expectations for inputs.'],['Rollback','A controlled return to an earlier approved behavior or safe alternative.']],
[['Make inputs reproducible','Record the query, transformations, prediction cutoff and feature definitions. Ensure identifiers join correctly and future labels do not leak into scoring. Separate development and production access and grant only the required permissions.'],
['Choose the serving pattern','A nightly forecast may be computed in a scheduled batch, while an immediate user decision may need a request-time service. Account for cost, latency, freshness and failure handling. A successful scheduled job does not prove the output was used correctly.'],
['Monitor the outcome and ownership','Track missing inputs, schema changes, scoring failures and later quality evidence. Assign who investigates alerts, approves updates and communicates limitations. Keep a documented fallback that users can actually use when the model is unavailable.']],
'A fictional retailer generates store-level forecasts each night from approved historical sales tables. Managers receive the next morning’s results with generation time and model version. The system must distinguish zero predicted demand from a missing or failed forecast.',
['Version the query and transformation that produces each store’s features. Test them on a representative historical cutoff.','Run a limited deployment and reconcile store counts, units, forecast horizons and access permissions before broader use.','If the upstream table is late, label output stale or use an approved fallback. Do not silently present yesterday’s prediction as newly computed.'],
'Deployment can amplify a modest modeling error by repeating it across many decisions; automation does not make a result self-validating.',
'Why should a prediction include a generation time or model version?',
'They help users interpret freshness, compare changes and investigate which inputs and behavior produced a result.',
'A scheduled scoring task succeeds but writes predictions in dollars where users expect units. Is the deployment healthy?',
'No. Technical execution succeeded while the data contract failed. Validate semantic units and user-visible outcomes, not only job status.',
['database-transactions','model-drift-and-monitoring','data-wrangling-feature-engineering'],[r('Snowflake: Documentation guides','https://docs.snowflake.com/en/guides'),r('Google: Production ML systems','https://developers.google.com/machine-learning/crash-course/production-ml-systems')]),
t('generative-ai-business-value','Predictive versus generative AI, business value and decision strategy','Intermediate',
'Predictive analytics estimates outcomes or categories; generative AI produces content such as text or images. A useful strategy ties either capability to a measurable workflow and appropriate controls.',
'The distinction concerns the application’s job, not an absolute separation of mathematics: language generation often uses predictive training objectives. A forecast helps estimate demand; a language model might draft an explanation of that forecast. Neither automatically determines a good decision. Business value combines changes in revenue, cost, quality, risk and strategic capability. Measure the baseline and the full workflow, including verification, integration and maintenance. A persuasive output can create new work or harmful overconfidence rather than a net benefit.',
'Learn to choose a suitable AI use case, quantify net value and decide how much autonomy evidence supports.',
[['Baseline','The current or simpler alternative used for comparison.'],['Net benefit','Benefit after relevant costs and adverse effects under a stated model.'],['Guardrail','A condition that must remain acceptable while pursuing an objective.']],
[['Identify the required output','A classification, numerical forecast, draft document and autonomous action have different evaluation needs. If the objective is a reliable answer from policy, search or rules may outperform free-form generation. Select the method after defining the task.'],
['Measure the complete workflow','Include time spent checking outputs, correcting errors, managing data and supporting users. False positives and false negatives can have asymmetric business and human costs. A single accuracy percentage is not a complete value model.'],
['Pilot with boundaries','Define permitted uses, protected data, review responsibilities and stop criteria. Compare against the baseline on representative cases, not only enthusiastic users. Expand only where evidence supports usefulness and manageable risk; retain a way to contest consequential errors.']],
'A fictional reporting team saves 8 hours per week using drafts but spends 5 new hours checking and correcting them. At an assumed $40 per hour, net labor benefit is 3 × $40 = $120 weekly before tool, integration and other costs.',
['Separate gross time saved from net time saved. Specify whether quality or turnaround also changes.','If recurring tool cost is $150 weekly, the simplified labor-only comparison is negative $30. Other benefits need their own evidence rather than being invented to justify adoption.','Evaluate document accuracy and privacy constraints before expanding use. A financial saving cannot automatically offset an unacceptable violation of a guardrail.'],
'Generated content that looks complete can conceal invented facts, uncertain ownership, privacy exposure or a shift of work to less visible staff.',
'Does a generative model eliminate the need for predictive methods?',
'No. The task determines what is needed. Generation can complement forecasting or classification without replacing appropriate quantitative evaluation.',
'Why should a business case include error correction and oversight time?',
'Those are part of the delivered workflow. Excluding them can turn a gross productivity claim into a misleading estimate of actual benefit.',
['tokens-and-context','precision-and-recall','ai-project-lifecycle-strategy'],[ml,ai]),
t('exploratory-data-statistics','Exploratory analysis, data types and descriptive statistics','Beginner',
'Exploratory data analysis examines structure, quality and patterns before formal modeling. Descriptive statistics summarize what the observed data contain, not automatically what a wider population does.',
'Begin by understanding the unit represented by each row and the meaning of each field. A category such as department differs from a count or continuous measurement. Ordered ratings are not automatically equally spaced quantities. Means, medians, quantiles and measures of spread answer different questions. Exploration is useful for generating hypotheses and detecting problems, but repeatedly inspecting data and then reporting only a surprising pattern can exaggerate evidence. Keep exploratory discoveries distinct from later confirmatory tests.',
'Learn to choose a useful summary, detect misleading aggregation and ask what a dataset actually represents.',
[['Unit of analysis','The entity or event represented by an observation.'],['Median','The middle value of an ordered sample, with a defined convention for even sizes.'],['Spread','How dispersed the observations are, rather than their typical level.']],
[['Check types and definitions','A numerical ID is a label, not a meaningful quantity to average. Identify categorical, ordered and numerical variables, units and missing-value codes. A zero waiting time differs from an unknown waiting time. Document those distinctions before calculating summaries.'],
['Compare center and spread','The mean uses all values and is sensitive to extremes. The median describes the middle rank. Standard deviation, range and interquartile range describe different aspects of variability. Show a distribution so one summary does not hide skew or distinct subgroups.'],
['Explore relationships carefully','Use grouped summaries and appropriate plots to inspect trends, outliers and correlations. Check denominators, repeated observations and aggregation. An overall relationship can differ across groups. Record plausible explanations without presenting an exploratory pattern as causal proof.']],
'Five fictional waiting times are 2, 3, 3, 4 and 28 minutes. The mean is 40 ÷ 5 = 8 minutes; the median is 3. Both are correct calculations but communicate different features of the same small sample.',
['Order the observations and inspect the 28-minute case. Confirm it is a real event rather than a unit or entry error.','Report the long wait alongside a typical-value measure. Deleting it merely because it is inconvenient would hide part of the service experience.','Compare groups or time periods only after checking whether their definitions and collection methods match. A dashboard should explain what the numbers represent.'],
'An outlier is a reason to investigate, not automatic permission to remove an observation.',
'Why can the mean waiting time exceed the wait experienced by most people?',
'A small number of very large waits can pull the mean upward. The median and a distribution plot help communicate that asymmetry.',
'Would averaging customer ID numbers describe the average customer?',
'No. Those numbers identify customers; numerical arithmetic on identifiers generally has no substantive interpretation.',
[],[nist,ml]),
t('visual-storytelling-bi','Visual storytelling, interactive charts and Power BI','Beginner',
'Data visualization encodes measurements in visual form. A useful data story connects a clear question, appropriate comparisons and uncertainty to a defensible decision.',
'Choose a chart for the relationship being investigated. Bars compare categories, lines often show ordered time, scatterplots reveal paired numerical relationships and histograms summarize distributions. Static charts support a stable argument; interactive tools permit exploration through filters and linked views. Power BI connects data preparation, modeling, visualization and sharing, while Excel supports tabular analysis and charting. A tool’s visual polish cannot validate the data or prevent a misleading comparison. An audience needs definitions and context as well as an attractive display.',
'Learn to choose a chart, explain what readers may conclude and keep interactive filters from hiding important context.',
[['Encoding','Mapping a value to position, length, color or another visual property.'],['Denominator','The total relative to which a count or rate is interpreted.'],['Filter context','The subset of data currently included in a view or calculation.']],
[['State the audience’s question','Executives may need a comparison supporting a decision, while analysts need detail to investigate exceptions. Start with the question and choose a chart that directly answers it. Do not select a complex display simply because the software offers one.'],
['Protect honest comparison','Label units and periods, explain exclusions and use scales that do not exaggerate differences. Bar lengths generally need a meaningful zero baseline. Avoid relying on color alone, and provide readable labels or a data table for accessibility.'],
['Make interaction legible','Show active filters and allow reset. Ensure totals and rates respond consistently. A missing-data category should not disappear without explanation. Distinguish an association shown in a chart from an intervention that caused the change.']],
'Two support teams report 20 and 40 complaints. Team A handled 100 cases and B handled 1,000. A count-only bar chart suggests B is worse, while the complaint rates are 20 percent and 4 percent respectively.',
['Choose whether the question concerns complaint workload or customer-level complaint frequency. Those require different denominators.','Show both counts and rates where useful, with the same time window and definitions.','Add a region filter in a dashboard and clearly display its selection. Confirm that both the numerator and denominator reflect that region.'],
'A persuasive narrative can be misleading if it suppresses uncertainty, changes scales selectively or mistakes a correlation for an explanation.',
'Why should an interactive dashboard show which filters are active?',
'Otherwise readers can mistake a subset for the full population, compare incompatible views or misunderstand changing totals.',
'A line chart rises after a product change. Does the chart prove the change caused improvement?',
'No. Other events, seasonality, selection and measurement changes may explain the trend. The chart suggests a question; causal evidence requires a suitable design.',
['exploratory-data-statistics'],[r('Microsoft: Power BI overview','https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview'),nist]),
t('probability-distributions','Probability, distributions and expected values','Beginner',
'A probability distribution describes possible outcomes and their likelihoods. It models uncertainty under assumptions; it is not a promise about the next observation.',
'A discrete variable takes separate values such as a count of arrivals; a continuous variable models quantities such as duration. A valid probability model assigns nonnegative likelihoods that total one across all possibilities. Expected value is a probability-weighted average, not necessarily a possible single outcome. Different families describe different situations: Bernoulli models a binary result, binomial a count across specified trials, Poisson a count under rate assumptions and normal a symmetric continuous pattern. Selection must follow the process and evidence.',
'Learn to build a small probability table, calculate its expected value and recognize when a distributional assumption needs scrutiny.',
[['Random variable','A numerical quantity whose value depends on an uncertain outcome.'],['Expected value','A probability-weighted average under a specified model.'],['Independence','A condition where learning one event does not alter another’s probability in the relevant sense.']],
[['Define outcomes and units','Distinguish customer arrivals per hour from minutes between arrivals. They are related but different variables. Specify the time interval, population and possible bounds before choosing a distribution. A normal model can produce impossible negative values for some quantities.'],
['Match assumptions to the process','Binomial reasoning commonly assumes a fixed trial count, common success probability and independence. Real customers or events may influence each other. A familiar distribution should not be selected only because its spreadsheet function is convenient.'],
['Compare average with variability','Two processes can share an expected value but differ greatly in spread and extreme outcomes. Inspect probabilities of consequential thresholds and the shape of the distribution, not just the mean. Test sensitivity to uncertain distribution parameters.']],
'A fictional daily demand model assigns probability 0.2 to 0 units, 0.5 to 10 units and 0.3 to 20 units. Probabilities total 1. Expected demand is 0 × 0.2 + 10 × 0.5 + 20 × 0.3 = 11 units.',
['List every modeled outcome and verify that probabilities are valid and sum to one.','Calculate the weighted average, keeping the demand unit consistent. Eleven is an average across repeated modeled days, not one of the listed daily outcomes.','If stock is 10, the model’s shortage probability is 0.3. That threshold question may matter more operationally than the average.'],
'A distribution fitted to historical observations may fail when the process, population or measurement changes.',
'Must the expected value be an outcome that can occur?',
'No. A binary variable with equal probabilities has expected value 0.5 even though each realized result is zero or one.',
'Two equally likely payoffs are $0 and $100. Is the expected $50 a guaranteed payment?',
'No. The expected value is $50, but the modeled individual outcomes remain $0 or $100. The average does not remove risk.',
['exploratory-data-statistics'],[nist,r('Google: ML glossary','https://developers.google.com/machine-learning/glossary')]),
t('sampling-confidence-intervals','Samples, sampling distributions and confidence intervals','Intermediate',
'A sample is a subset used to learn about a population. A sampling distribution describes how a statistic varies across repeated samples under a specified design.',
'The variability among individual observations differs from uncertainty in an estimated population quantity. Standard error describes a statistic’s sampling variability under assumptions. Confidence intervals use a procedure with a stated long-run coverage property. For a conventional 95 percent frequentist interval, the method would contain the fixed target parameter in about 95 percent of repeated samples when its assumptions hold. That is not a guarantee about one interval or a claim that 95 percent of individual observations fall inside it.',
'Learn to distinguish spread from estimation uncertainty and interpret an interval without overlooking sampling bias.',
[['Population','The group or process about which a conclusion is intended.'],['Standard error','An estimate of a statistic’s variability across repeated samples.'],['Coverage','The fraction of repeated intervals containing the target under the procedure’s assumptions.']],
[['Inspect how the sample was obtained','A large convenience sample can systematically miss relevant groups. Random sampling supports particular inferential calculations, but nonresponse, clustering and measurement error still matter. More rows do not repair a biased recruitment process automatically.'],
['Separate two kinds of variation','Customer waiting times may vary widely while their mean is estimated fairly precisely from many suitable observations. Increasing sample size tends to reduce standard error under common independent-sampling assumptions; it does not make individual waits less variable.'],
['Read the interval in context','Identify the parameter, units, method and assumptions. Wider confidence coverage typically requires a wider interval with other conditions fixed. An interval accounts for the modeled uncertainty, not every possible bias or data-quality problem.']],
'In a simplified large-sample example, a sample mean is 50 minutes and its estimated standard error is 2 minutes. Using a normal approximation, a 95 percent interval is 50 ± 1.96 × 2, or approximately 46.08 to 53.92.',
['Check that the approximation and sampling design are appropriate; a formula alone is not enough.','Interpret the interval as about the population mean under the method, not a range containing 95 percent of individual waiting times.','Investigate missing night-shift observations. The calculated interval may be narrow while the target population is poorly represented.'],
'Statistical precision can create false confidence when selection or measurement bias is omitted from the analysis.',
'Does a 95 percent confidence interval mean 95 percent of customers wait within its bounds?',
'No. An interval for the mean concerns uncertainty about a population average. Individual waiting-time variation is a different quantity.',
'Would doubling a biased sample necessarily make the conclusion more representative?',
'No. It may reduce modeled random error while preserving the same systematic bias. Sampling design and coverage must be examined.',
['probability-distributions'],[r('NIST: Confidence intervals','https://www.itl.nist.gov/div898/handbook/prc/section1/prc14.htm'),nist]),
t('hypothesis-testing-ab','Hypothesis testing, A/B experiments and practical significance','Intermediate',
'A hypothesis test evaluates how compatible observed data are with a specified null model. An A/B experiment assigns alternatives to comparable units to estimate their effects.',
'A p-value is calculated under the null hypothesis and relevant assumptions; it is not the probability that the null is true. A small p-value does not measure effect size or business importance. Tests can make false-positive and false-negative errors, and repeated comparisons or stopping as soon as a result looks favorable can distort interpretation. A good experiment specifies its objective, assignment unit, outcome, sample plan and analysis before inspecting results. Ethical and operational constraints also affect whether experimentation is appropriate.',
'Learn to design a credible comparison and communicate both uncertainty and practical consequences.',
[['Null hypothesis','A specified reference claim or model, such as no difference in a defined mean.'],['Type I error','Rejecting the null when it is true under the test’s framework.'],['Power','Probability of detecting a specified alternative under stated assumptions.']],
[['Define the decision and effect','Decide which outcome matters and what magnitude would justify a change. Conversion rate, processing time and complaints can move differently. Preselect the primary measure and relevant guardrails so a favorable metric is not chosen after the fact.'],
['Assign and analyze correctly','Random assignment helps balance confounders on average. Users, classrooms and transactions are different assignment units; interference or repeated measures can break simplistic independence assumptions. Confirm exposure and data quality before interpreting a difference.'],
['Report more than a threshold','Give group counts, effect estimates, intervals, limitations and practical costs. Failure to reject does not prove equality. A statistically detectable tiny gain may not offset deployment, maintenance or user harm.']],
'A hypothetical signup experiment has 1,000 users in each group. A gets 100 signups and B gets 120. Observed rates are 10 percent and 12 percent: a 2 percentage-point increase and a 20 percent relative increase.',
['Keep absolute and relative changes distinct. Neither number alone establishes statistical uncertainty.','Use the planned analysis appropriate to assignment and sample size, and report an interval rather than inferring significance from the raw difference alone.','Check guardrails such as accidental signups or unsubscribe rates. More signups are not necessarily better if consent quality declines.'],
'Do not keep trying outcomes, subgroups and stopping dates until one produces a desirable p-value.',
'Does a p-value of 0.03 mean there is a 97 percent probability the tested treatment works?',
'No. That interpretation reverses the conditional statement and ignores the model and assumptions. Effect estimation and decision relevance need separate reasoning.',
'A huge sample detects a one-second time saving that costs more to implement than it saves. Must it be launched?',
'No. Statistical evidence of a difference and a beneficial decision are different questions. Consider magnitude, costs, risks and affected users.',
['sampling-confidence-intervals','causal-inference'],[nist,r('NIST: Hypothesis testing','https://www.itl.nist.gov/div898/handbook/prc/section1/prc16.htm')]),
t('data-wrangling-feature-engineering','Data wrangling, variable selection and feature engineering','Intermediate',
'Data wrangling makes records usable and consistent. Feature engineering creates model inputs, while variable selection chooses which inputs to retain.',
'The data-to-insight pipeline includes definitions, joining, cleaning, transformation, exploration, modeling and communication. A spreadsheet or visual analytics tool can make transformations easy to apply, but it can also hide incorrect joins or implicit conversions. Missingness, duplicates, units and outliers need explicit policies. Feature selection should respect prediction time and be performed within a proper evaluation pipeline. A highly predictive variable may be a leak, a proxy for a protected characteristic or a consequence rather than a cause.',
'Learn to audit a practical preparation pipeline in Excel or an analytics tool without letting convenience override validity.',
[['Join key','A field or set of fields used to connect records.'],['Feature','An input representation available to the model at prediction time.'],['Imputation','Replacing missing values under an explicit method and assumptions.']],
[['Establish provenance and row meaning','Record where each field came from, its units and update timing. A join from one customer to many transactions changes row count; an unintended many-to-many join can multiply observations. Check counts and totals before and after every major transformation.'],
['Transform with a rationale','Choose missing-value treatments, scaling, encoding and derived features to match the task. Do not interpret a missing purchase amount as zero by default. Fit learned preprocessing on training data, then apply it consistently to evaluation data.'],
['Use tools transparently','In Excel, keep raw inputs distinct from calculated columns, document formulas and check filters. Analytic Solver can fit models and compare results; Power Query can record preparation steps. Version features and verify their availability in the deployed workflow.']],
'A fictional churn table joins customer records with support tickets. Customer A has three tickets, so the join creates three rows for that person. A naïve model split can then place the same customer in training and testing.',
['Confirm whether the intended prediction unit is a customer or a ticket. If customer-level, aggregate ticket features at an appropriate cutoff date.','Create features such as ticket count before the prediction date, not a later cancellation flag.','Split by customer and time where appropriate. Compare the resulting honest score with the earlier inflated result, explaining why a lower number can be more credible.'],
'Automated feature selection cannot determine whether data use is lawful, fair or available at the moment an operational decision must be made.',
'Why should you inspect row counts after a join?',
'A join can duplicate, omit or multiply records depending on key uniqueness. Those changes can distort summaries, targets and model evaluation.',
'Should an outlier always be capped before training?',
'No. Check whether it is an error, a legitimate rare case or an important risk. The treatment should be justified and tested rather than chosen to improve a headline score.',
['data-leakage','exploratory-data-statistics'],[ml,r('Microsoft: Power Query overview','https://learn.microsoft.com/en-us/power-query/power-query-what-is-power-query')]),
t('ai-project-lifecycle-strategy','AI project lifecycles, strategy and prioritization','Beginner',
'A project is temporary work intended to create a defined result. Managing an AI project connects that result to a business objective, a delivery approach and evidence of benefit.',
'A model is only one part of a product. Data access, workflow integration, permissions, operations and the ability to act on outputs all affect whether the investment helps anyone. A project manager coordinates this work across initiation, planning, execution, monitoring and closure. Those activities can overlap and repeat. Strategy determines which problem deserves resources; a project plan explains how a selected intervention will be delivered. A completed technical task is not automatically a realized business benefit.',
'Learn to connect an AI proposal to a measurable problem, prioritize alternatives and distinguish delivery milestones from benefits.',
[['Sponsor','The accountable supporter who helps authorize and sustain the initiative.'],['Benefit','A useful change in outcomes, not merely a delivered feature.'],['Baseline','An agreed starting point for measuring later change.']],
[['Start with the decision','Write who faces a problem, what action is difficult and what improvement would matter. “Use AI” describes a possible means, not the objective. Compare non-AI alternatives before committing to a model.'],
['Select under constraints','Compare strategic fit, expected benefit, feasibility, data readiness, risk and opportunity cost. A weighted score can structure discussion, but mandatory safety or legal requirements should not disappear into an attractive average. Include the option to defer or stop.'],
['Choose the way of working','Use short evidence-building iterations where requirements or data are uncertain, while controlling commitments that require formal approval. PMI’s Talent Triangle distinguishes ways of working, power skills and business acumen: method, collaboration and commercial understanding must work together.']],
'A fictional support team spends 30 hours per week routing messages. It considers a new AI classifier, improved form categories and a simple rule-based router. The objective is less routing effort without more harmful misrouting, not the highest possible benchmark score.',
['Measure current time and important errors before changing the workflow. Identify who can verify whether time is actually saved.','Pilot the alternatives on representative cases. Include integration and review effort in the comparison, not just model accuracy.','Agree a go/no-go threshold and who owns benefit measurement after handover. Close a project that cannot justify further investment rather than hiding a failed assumption.'],
'Do not confuse a busy delivery team or an impressive demonstration with evidence that the selected problem is worth solving.',
'Is a deployed model sufficient evidence of project success?',
'No. Deployment is a delivery milestone. Success also depends on operational use, acceptable risk and measured improvement against the objective.',
'A manual process takes 20 hours weekly, and an AI pilot saves 5 but adds 8 hours of checking. Has labor effort improved?',
'Not on those figures: net effort increases by 3 hours. Investigate quality benefits separately, but do not report the 5-hour gross saving as the net outcome.',
[],[r('PMI: Talent Triangle','https://www.pmi.org/certifications/certification-resources/maintain/talent-triangle'),pmi]),
t('stakeholders-structures-culture','Stakeholders, organizational structures and project leadership','Intermediate',
'Stakeholder management identifies affected people, their interests and their decision rights. Organizational structure and culture influence how project authority and communication work.',
'An AI system changes work for people who may never use its interface. Operators, customers, data owners, legal teams and people being evaluated can all be stakeholders. In a functional structure, authority often follows departments; a matrix shares responsibilities across functional and project lines; a project-focused structure gives the project a more dedicated team. None eliminates conflict. Culture shapes whether bad news is surfaced early, whether people can challenge a sponsor and whether formal approval reflects actual understanding.',
'Learn to make decision rights explicit and engage affected people instead of treating a stakeholder list as a communication checklist.',
[['Stakeholder','A person or group affected by, interested in or able to influence the work.'],['Decision right','Authority to approve, reject or change a particular matter.'],['Escalation','Raising an unresolved issue to the appropriate decision owner.']],
[['Map more than influence','Record both power and exposure to harm. A low-power group may bear substantial consequences, so an influence-only matrix can exclude exactly the people who need representation. Ask what they need to understand and how they can contest decisions.'],
['Resolve authority conflicts','Identify who allocates people, who accepts requirements and who authorizes launch. In a matrix, a project manager may not control a specialist’s available hours. Surface these constraints before promising delivery dates.'],
['Lead through evidence and dialogue','Use listening, negotiation and clear expectations to build cooperation. A communication plan should specify purpose, audience, channel, cadence and an action owner. Make disagreement and unresolved assumptions visible rather than equating silence with agreement.']],
'A school’s data team proposes an attendance-risk model. The principal funds it, IT operates it, teachers use it and families experience its consequences. A technically complete design can still fail if families cannot correct erroneous records.',
['List approval owners for data use, security, educational practice and launch. Do not assign all decisions vaguely to “the team.”','Interview teachers and affected families about plausible errors and needed review paths. Record concerns alongside technical requirements.','If a specialist is allocated to two projects, obtain an explicit capacity decision. Update the schedule rather than assuming both managers have full access to the same person.'],
'Strong sponsorship is valuable but does not substitute for consultation, appropriate authority or a genuine mechanism for affected people to challenge errors.',
'Why is a stakeholder register not the same as stakeholder engagement?',
'A register records people and interests. Engagement requires listening, responding, checking understanding and showing how concerns influence decisions.',
'Two managers assign the same analyst full-time work for the same week. Is this mainly a productivity problem?',
'It is first a capacity and authority conflict. The plan must reconcile allocations and priorities; expecting the analyst to quietly absorb both assignments hides the real issue.',
['ai-project-lifecycle-strategy'],[pmi,ai]),
t('scope-wbs-communications','Scope, work breakdown structures and communication plans','Intermediate',
'Scope defines the work and results included in a project. A work breakdown structure decomposes that scope into manageable deliverables and work packages.',
'A scope statement makes boundaries and acceptance criteria visible. A WBS answers what must be delivered, rather than when every task happens or who reports to whom. Work packages provide a basis for estimating, scheduling and responsibility assignment. Requirements, scope and a schedule are connected but different. Change control evaluates a proposed alteration’s impact before changing the agreed plan. Communication supports those decisions by reaching the right audience with information they can use, not by producing the maximum number of status messages.',
'Learn to turn an ambiguous AI request into deliverables, acceptance criteria and a controlled conversation about changes.',
[['Deliverable','A verifiable output or capability to be accepted.'],['Work package','A manageable component at the chosen lower level of a WBS.'],['Acceptance criterion','A condition used to judge whether a result meets its purpose.']],
[['Define inclusion and exclusion','For a newsletter, state whether email preferences, payments, audio and a learning library are included. “Build the platform” hides those choices. Include data, testing, security and handover work that users do not directly see.'],
['Decompose without losing work','Break the scope into deliverables whose combined coverage represents the agreed project. Avoid duplicating the same work under several branches. Estimate only after the team understands what each package actually contains.'],
['Communicate changes as decisions','A new request should identify its benefit, effort, dependencies and risk. Tell the sponsor what commitment would change and who must approve it. Tailor progress reports: executives need decisions and impacts; implementers need actionable detail.']],
'An AI support pilot includes a labeled dataset, a routing service, a review interface and operational handover. “Train model” is insufficient as the whole WBS because it excludes the workflow that makes the prediction useful.',
['Give each deliverable an acceptance owner and measurable conditions. A review interface must handle ambiguous and failed cases, not merely display a score.','Derive activities and dependencies from the packages. The WBS itself is not yet the time-ordered schedule.','A request for multilingual support adds labeling and evaluation work. Review that impact before silently adding it to the promised launch.'],
'A polished WBS cannot compensate for missing requirements or acceptance criteria that measure only technical completion.',
'How does a WBS differ from a schedule?',
'The WBS organizes scope into deliverables and work packages. A schedule adds activities, durations, sequencing and resource-related timing.',
'A sponsor asks for another feature “because the team is already working on that screen.” What should be checked?',
'Check the actual data, implementation, testing and support impact. Nearby interface placement does not establish that the change is small or already included.',
['ai-project-lifecycle-strategy'],[r('PMI: WBS principles','https://www.pmi.org/learning/library/work-breakdown-structure-basic-principles-4883'),pmi]),
t('estimates-critical-path-resources','Estimates, critical paths and resource scheduling','Intermediate',
'A project schedule combines activities, dependencies, duration estimates and resource availability. The critical path constrains the earliest finish under the stated schedule assumptions.',
'An effort estimate is not a calendar duration. A task needing 20 hours of work may span several days if a specialist is available only part time. Dependencies determine which work can start; resource constraints can create additional delays. Estimates should identify assumptions and uncertainty rather than imply that a single number is certain. Microsoft Project and similar tools can calculate dates from a model, but accurate calculations cannot repair incorrect dependencies, calendars or capacity inputs.',
'Learn to calculate a simple critical path, detect resource over-allocation and evaluate options for shortening a project.',
[['Dependency','A relationship constraining the order of activities.'],['Float','Schedule flexibility before an activity delays the relevant finish under the model.'],['Crashing','Adding resources or cost to shorten suitable activities.']],
[['Build the network','Translate WBS packages into activities and justified dependencies. Distinguish unavoidable technical order from habitual sequencing. Record working calendars, external lead times and available resources so the network reflects how work can actually happen.'],
['Find the constraint','Compare complete dependency paths. The longest-duration path constrains finish in a basic unconstrained network. A short activity can be critical if it has no float; a long one may have flexibility. Recheck after any change.'],
['Shorten responsibly','Fast-tracking overlaps work, increasing rework or coordination risk. Crashing adds suitable capacity, often at extra cost. Resource leveling may extend finish to resolve over-allocation. Protect quality, safety and sustainable human workload rather than compressing every estimate.']],
'After a two-day data-access task, labeling takes four days while interface work takes three days. A final one-day integration task needs both branches. Assume unlimited suitable resources, whole working days and no other dependencies.',
['The labeling path totals 2 + 4 + 1 = 7 days. The interface path totals 2 + 3 + 1 = 6 days. The earliest modeled finish is seven days.','Reducing interface work by a day does not shorten that finish. Reducing labeling by one day may, if all other assumptions hold.','If the same analyst must do both branches sequentially, the unlimited-resource estimate no longer applies. Update assignments and recompute dates in the scheduling tool.'],
'More people do not automatically reduce a task’s duration proportionally; coordination, indivisible work and learning time can offset gains.',
'Why might a schedule with valid task dependencies still be impossible?',
'It may allocate the same resource to simultaneous work beyond available capacity or omit calendars, external delays and practical constraints.',
'Would shortening a noncritical activity always improve the project finish?',
'No. If it retains float and does not release a constrained resource, the critical finish can remain unchanged. Analyze the whole network.',
['scope-wbs-communications'],[pmi,r('PMI: WBS and project lifecycle','https://www.pmi.org/learning/library/applying-work-breakdown-structure-project-lifecycle-6979')]),
t('project-risk-performance-closure','Project risk, earned value, performance and closure','Advanced',
'Risk management plans for uncertain effects on objectives. Performance control compares evidence with a baseline; closure verifies acceptance, handover and unresolved obligations.',
'A risk is an uncertain event or condition, while an issue has already occurred. Record causes, consequences, owners, responses and triggers, not just colored ratings. During delivery, progress must be tied to accepted work rather than optimistic percentage estimates. Earned value combines budgeted work and actual cost under a defined baseline. It supplements—not replaces—quality, benefits and model-risk measures. Closure is a controlled transition to ownership and support, not simply the date a team stops coding.',
'Learn to read basic earned-value indicators and connect them with risk responses and operational handover.',
[['PV','Planned value: budgeted value of work scheduled by a date.'],['EV','Earned value: budgeted value of work actually completed.'],['AC','Actual cost incurred for the measured work.']],
[['Plan responses and ownership','Choose avoidance, mitigation, transfer or acceptance where appropriate, and identify residual risks. A risk register needs review dates and triggers. Data-access failure, label quality and deployment harm deserve attention alongside schedule risks.'],
['Interpret progress consistently','Cost performance index is EV divided by AC; schedule performance index is EV divided by PV. Values below one can flag cost or progress shortfalls under the baseline. A schedule index is not a direct number of calendar days late.'],
['Close with a usable handover','Confirm acceptance criteria, support ownership, data and access arrangements, remaining defects, contractual obligations and benefit measurement. Capture lessons about failed assumptions so later teams can act on them. An owner must accept any remaining operational risk.']],
'A fictional pilot has PV $10,000, EV $8,000 and AC $12,000 at the reporting date. Its model also fails a required subgroup quality check. These are separate kinds of evidence that a status report must not average away.',
['CPI = 8,000 ÷ 12,000 ≈ 0.67: each dollar spent has earned about $0.67 of budgeted work value under this baseline.','SPI = 8,000 ÷ 10,000 = 0.8: less budgeted work is complete than planned. Neither ratio establishes that the model is safe.','Investigate causes and response options. Do not close as successful until acceptance and risk criteria are addressed and the receiving owner can operate the system.'],
'Completing work that fails acceptance criteria can inflate apparent progress; earned value depends on credible definitions of completion.',
'Does spending less than the planned budget prove favorable performance?',
'No. Less may have been delivered, quality may be unacceptable or important costs deferred. Compare completed scope, actual cost, timing and outcomes.',
'A model is ready but no team accepts monitoring responsibility. Is handover complete?',
'No. Operational ownership is part of the deliverable. Closing without it leaves failures and user impacts unmanaged.',
['estimates-critical-path-resources'],[r('PMI: Earned value management','https://www.pmi.org/learning/library/earned-value-management-system-performance-6597'),ai]),
t('cpmai-patterns-iteration','CPMAI, AI application patterns and iterative delivery','Intermediate',
'A data-centered AI project method connects business understanding, data work, modeling, evaluation and operational use through repeated evidence-based decisions.',
'CPMAI provides a structured way to manage AI initiatives rather than assuming ordinary software delivery alone captures their uncertainties. Its six broad phases concern business understanding, data understanding, data preparation, model development, model evaluation and operationalization. Iteration is essential when the data cannot support the desired objective or evaluation exposes an unmet need. Framework terminology helps organize work; it is not evidence that a particular project is feasible, ethical or valuable.',
'Learn to identify an AI application pattern and select the next evidence-building step when a pilot fails.',
[['Operationalization','Integrating and maintaining a usable capability in its real workflow.'],['Iteration','Revisiting assumptions and activities based on evidence.'],['Pattern','A recurring type of application problem, not a guarantee of one implementation.']],
[['Classify the purpose','PMI’s seven patterns cover recognition, conversation and human interaction, predictive analytics and decisions, patterns and anomalies, hyper-personalization, autonomous systems and goal-driven systems. A use case may combine several. Identify the action and evidence requirements, not merely a fashionable model family.'],
['Test data readiness','Check access rights, quality, label meaning, representativeness and whether the needed information exists at decision time. A demonstration using hand-selected examples does not establish production readiness. Data limitations can require redesigning the objective.'],
['Evaluate before expanding autonomy','Compare with a useful baseline and examine costly errors and affected groups. Operationalization includes monitoring, review, rollback and ownership. A failed evaluation should trigger diagnosis and iteration, not simply a larger model purchase.']],
'A support assistant combines conversation with recognition of request types. It performs well on routine English messages but fails on ambiguous multilingual requests that matter to the service population.',
['Return to business and data requirements: are these requests essential, and do labels and permissions support them?','Collect appropriate examples or narrow the pilot’s permitted scope with a safe review route. Compare the revised system with the baseline.','Only operationalize the supported behavior. Record unresolved limitations and monitor actual use rather than declaring the whole application solved.'],
'Following a methodology does not prove that training data are appropriate or that users receive the intended benefit.',
'Why can returning from evaluation to data preparation be good management?',
'It addresses evidence that the current inputs or representation cannot support the objective. Iteration is preferable to hiding a failed assumption.',
'Should a failed pilot automatically receive more training time?',
'No. First diagnose whether the issue is the objective, data, labels, implementation, evaluation or workflow. More optimization cannot repair every kind of failure.',
['ai-project-lifecycle-strategy','data-leakage'],[r('PMI: Six AI project stages','https://www.pmi.org/blog/6-stages-to-run-a-successful-ai-project'),r('PMI: Seven patterns of AI','https://www.pmi.org/blog/seven-patterns-of-ai')]),
];
